#define main archived_library_audit_main
#include "/workspace/scratch/a9592b052b11/cs80-work/tests/LibraryAuditTests.cpp"
#undef main
#include <iomanip>
#include <iostream>

int main(int argc, char** argv) {
    const std::set<std::string> names = {"Neon Brass 18", "Velvet Strings 38", "Neon Strings 40", "Dark FX 148", "Sforzando Brass", "Swell Strings", "Spiccato Strings", "Clarinet", "Bass Clarinet", "Metallic Keys"};
    std::vector<FactoryPreset> bank(originalLibrary());
    bank.insert(bank.end(), curatedLibrary().begin(), curatedLibrary().end());
    const int mode = argc > 1 ? std::atoi(argv[1]) : 0;
    for (auto p:bank) {
        if (!names.contains(p.name)) continue;
        if (mode == 1) {
            for (int ch=0; ch<2; ++ch) p.values[chParam(ch, CP_vLevel)] = 1.0f;
        }
        if (mode == 2) {
            for (int ch=0; ch<2; ++ch) p.values[chParam(ch, CP_vLevel)] = 1.0f;
            if (p.name == "Spiccato Strings" || p.name == "Neon Strings 40")
                p.values[chParam(0, CP_vD)] *= 1.6f;
        }
        if (mode == 3) {
            if (p.name == "Sforzando Brass" || p.name == "Neon Brass 18") {
                p.values[chParam(0, CP_vLevel)] = .72f;
                p.values[chParam(1, CP_vLevel)] = .40f;
            } else if (p.name == "Swell Strings" || p.name == "Velvet Strings 38") {
                p.values[chParam(0, CP_vLevel)] = .275f;
                p.values[chParam(1, CP_vLevel)] = .20f;
                p.values[chParam(0, CP_afterLevel)] = .8125f;
                p.values[chParam(1, CP_afterLevel)] = .6875f;
            } else if (p.name == "Spiccato Strings" || p.name == "Neon Strings 40") {
                p.values[chParam(0, CP_vLevel)] = 1.0f;
                p.values[chParam(1, CP_vLevel)] = .90f;
                p.values[chParam(0, CP_vD)] *= 0.30f / 0.26f;
            } else if (p.name == "Dark FX 148") {
                p.values[chParam(0, CP_vLevel)] = 1.0f;
                p.values[chParam(1, CP_vLevel)] = 1.0f;
                p.values[chParam(0, CP_lpfCutoff)] = 165.0f;
            } else if (p.name == "Clarinet") {
                for (int ch=0; ch<2; ++ch) for (int control : {CP_vLevel, CP_initLevel, CP_afterLevel})
                    p.values[chParam(ch, control)] = std::min(1.0f, p.values[chParam(ch,control)] * 1.40f);
            } else if (p.name == "Bass Clarinet") {
                for (int ch=0; ch<2; ++ch) for (int control : {CP_vLevel, CP_initLevel, CP_afterLevel})
                    p.values[chParam(ch, control)] = std::min(1.0f, p.values[chParam(ch,control)] * 1.55f);
            } else if (p.name == "Metallic Keys") {
                p.values[chParam(0, CP_vLevel)] = .82f;
                p.values[chParam(1, CP_vLevel)] = .53f;
            }
        }
        auto level=measure(p);
        std::cout << std::setprecision(9) << p.name << "\t" << dbfs(level.windowRms) << "\t" << dbfs(level.phrasePeak) << "\t" << dbfs(level.stressPeak) << "\t" << level.finite << "\n" << std::flush;
    }
}
